export type ParsedConfig = {
  name: string;
  enabled: boolean;
};

export function parseConfig(input: string): ParsedConfig {
  const values = new Map<string, string>();
  const pairs = input.split(';').map(part => part.trim()).filter(Boolean);

  for (const pair of pairs) {
    const separator = pair.indexOf('=');
    if (separator === -1) continue;
    values.set(pair.slice(0, separator).trim(), pair.slice(separator + 1).trim());
  }

  return {
    name: values.get('name') ?? 'default',
    enabled: values.get('enabled') === 'true',
  };
}
